import re
from collections import deque

class Solution:
    def findMinStep(self, board: str, hand: str) -> int:
        def clean(s):
            while True:
                t = re.sub(r'(.)\1{2,}', '', s)
                if t == s:
                    return s
                s = t

        start = clean(board) + '|' + ''.join(sorted(hand))
        q, seen, step = deque([start]), {start}, 0
        while q:
            for _ in range(len(q)):
                cur = q.popleft()
                b, h = cur.split('|')
                if not b:
                    return step
                for i in range(len(b) + 1):
                    for k, ch in enumerate(h):
                        if k and h[k] == h[k - 1]:
                            continue
                        nb = clean(b[:i] + ch + b[i:])
                        nh = ''.join(sorted(h[:k] + h[k + 1:]))
                        ns = nb + '|' + nh
                        if ns not in seen:
                            seen.add(ns)
                            q.append(ns)
            step += 1
        return -1

