                int j = i;
                while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
                if (j - i >= 3) d = false;
                else sb.append(s.substring(i, j));
                i = j;
            }
            s = sb.toString();
        }
        return s;
    }

    private String sorted(String h) {
        char[] a = h.toCharArray();
        Arrays.sort(a);
        return new String(a);
    }

    public int findMinStep(String board, String hand) {
        String start = clean(board) + "|" + sorted(hand);
        Queue<String> q = new LinkedList<>();
        Set<String> seen = new HashSet<>();
        q.add(start);
        seen.add(start);
        int step = 0;
        while (!q.isEmpty()) {
            int sz = q.size();
            while (sz-- > 0) {
                String cur = q.poll();
                int idx = cur.indexOf('|');
                String b = cur.substring(0, idx), h = cur.substring(idx + 1);
                if (b.isEmpty()) return step;
                for (int i = 0; i <= b.length(); i++)
                    for (int k = 0; k < h.length(); k++) {
                        if (k > 0 && h.charAt(k) == h.charAt(k - 1)) continue;
                        String nb = clean(b.substring(0, i) + h.charAt(k) + b.substring(i));
                        String nh = sorted(h.substring(0, k) + h.substring(k + 1));
                        String ns = nb + "|" + nh;
                        if (seen.add(ns)) q.add(ns);
                    }
            }
            step++;
        }
        return -1;
    }
}

