        b = clean(b);
        if (b.empty()) return 0;
        sort(h.begin(), h.end());
        string key = b + "|" + h;
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int res = INT_MAX;
        for (int i = 0; i < (int)b.size();) {
            int j = i;
