            int cnt = count(h.begin(), h.end(), b[i]);
            if (cnt >= need) {
                string nh = h;
                for (int k = 0; k < need; k++)
                    nh.erase(nh.find(b[i]), 1);
                int r = dfs(b.substr(0, i) + string(need, b[i]) + b.substr(j), nh);
                if (r >= 0) res = min(res, r + need);
            }
            i = j;
