import java.util.*;

class Solution {
    private Map<String, Integer> memo = new HashMap<>();

    private String clean(String s) {
        boolean d = false;
        while (!d) {
            d = true;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < s.length();) {
                int j = i;
                while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
                if (j - i >= 3) d = false;
                else sb.append(s.substring(i, j));
                i = j;
            }
            s = sb.toString();
        }
        return s;
    }

    private int dfs(String b, String h) {
        b = clean(b);
        if (b.isEmpty()) return 0;
        char[] a = h.toCharArray();
        Arrays.sort(a);
        String key = b + "|" + new String(a);
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        int res = Integer.MAX_VALUE;
        for (int i = 0; i < b.length();) {
            int j = i;
            while (j < b.length() && b.charAt(j) == b.charAt(i)) j++;
            int need = Math.max(0, 3 - (j - i));
            int cnt = 0;
            for (char c : a) if (c == b.charAt(i)) cnt++;
            if (cnt >= need) {
                String nh = h;
                for (int k = 0; k < need; k++)
                    nh = nh.replaceFirst(String.valueOf(b.charAt(i)), "");
                int r = dfs(b.substring(0, i) + String.valueOf(b.charAt(i)).repeat(need) + b.substring(j), nh);
                if (r >= 0) res = Math.min(res, r + need);
            }
            i = j;
        }
        int ans = res == Integer.MAX_VALUE ? -1 : res;
        memo.put(key, ans);
        return ans;
    }

    public int findMinStep(String board, String hand) {
        return dfs(board, hand);
    }
}

