  };
  const memo = {};
  const dfs = (b, h) => {
    b = clean(b);
    if (!b) return 0;
    const key = b + '|' + h.split('').sort().join('');
    if (key in memo) return memo[key];
    let res = Infinity;
    for (let i = 0; i < b.length;) {
      let j = i;
      while (j < b.length && b[j] === b[i]) j++;
      const need = Math.max(0, 3 - (j - i));
      let cnt = 0;
      for (const c of h) if (c === b[i]) cnt++;
      if (cnt >= need) {
        let nh = h;
        for (let k = 0; k < need; k++) nh = nh.replace(b[i], '');
        const r = dfs(b.slice(0, i) + b[i].repeat(need) + b.slice(j), nh);
        if (r >= 0) res = Math.min(res, r + need);
      }
      i = j;
    }
    return (memo[key] = res === Infinity ? -1 : res);
  };
  return dfs(board, hand);
};
